BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ap-server-q1', '稼働率とシステムの信頼性',
   '機器が「壊れてから次に壊れるまで」の平均間隔を表す指標を何というか。',
   NULL::text,
   '["MTBF（平均故障間隔）", "MTTR（平均修復時間）", "SLA（サービス品質保証）", "SPOF（単一障害点）"]',
   0, '[0]', 'single',
   '{"asked":"故障と故障の間の平均間隔を表す指標の名前を問う問題。","why_asked":"稼働率の計算式の分母を構成する2つの指標（MTBFとMTTR）を取り違えると計算全体が崩れるため、まず定義を正確に押さえさせる。","kid":"MTBFは「壊れにくさ」を表す数字。故障してから次に壊れるまでの間隔が長いほど、その機器は頑丈だといえる。","eg":"たとえるなら、電球が「切れてから次に切れるまで平均何時間持つか」という数字。長ければ長いほど良い電球。","terms":[["MTBF","Mean Time Between Failuresの略。直訳は「平均・時間・between（間の）・故障」。壊れてから次に壊れるまでの平均間隔"],["MTTR","Mean Time To Repairの略。直訳は「平均・時間・to（〜までの）・修理」。壊れてから直るまでの平均時間"]],"think":"「壊れにくさ」を表すのがMTBF、「直しやすさ」を表すのがMTTRという役割分担で覚える。稼働率はこの2つを組み合わせて計算する。","vs":"MTTRと混同しやすいが、MTBFは「故障の間隔（壊れにくさ）」、MTTRは「修理にかかる時間（直しやすさ）」で向いている方向が逆。","opt":["正解。故障してから次の故障までの平均間隔を表す指標。","MTTRは故障してから修理が終わるまでの平均時間を表す指標で、間隔ではなく修理にかかる時間を表す。","SLAはサービス提供者と利用者の間で取り決める品質保証の水準で、故障間隔を表す指標ではない。","SPOFはそこが壊れるとシステム全体が止まってしまう箇所を指す言葉で、時間を表す指標ではない。"]}'),

  ('ap-server-q2', '稼働率とシステムの信頼性',
   '機器が故障してから、修理が完了して復旧するまでにかかる平均時間を表す指標を何というか。',
   NULL::text,
   '["MTTR（平均修復時間）", "MTBF（平均故障間隔）", "RTO（目標復旧時間）", "RPO（目標復旧時点）"]',
   0, '[0]', 'single',
   '{"asked":"故障から復旧までの平均時間を表す指標の名前を問う問題。","why_asked":"MTTRはMTBFと対で稼働率の計算に使われるため、意味を取り違えると稼働率計算全体を誤る。","kid":"MTTRは「直しやすさ」を表す数字。修理にかかる時間が短いほど、そのシステムはすぐ復旧できるといえる。","eg":"たとえるなら、パンクした自転車のタイヤを直すのにかかる時間。短いほど早く乗れるようになる。","terms":[["MTTR","Mean Time To Repairの略。故障してから修理が終わるまでの平均時間"],["復旧","壊れた機器やシステムが元通り使える状態に戻ること"]],"think":"稼働率の計算では「壊れにくさ(MTBF)」と「直しやすさ(MTTR)」の両方が必要になる。MTTRが短いほど、たとえ故障してもすぐ復旧できるので稼働率は上がる。","vs":"RTO（目標復旧時間）と似た響きだが、MTTRは実績としての平均値、RTOは「これくらいで復旧させたい」という目標値である点が違う。","opt":["正解。故障してから修理が完了するまでの平均時間を表す指標。","MTBFは故障してから次の故障までの平均間隔を表す指標で、修理にかかる時間ではない。","RTOは災害復旧などで「どれくらいの時間で復旧させたいか」という目標値で、実績の平均時間を表す指標ではない。","RPOは「どの時点のデータまで復旧させたいか」という目標値で、修復にかかる時間を表す指標ではない。"]}'),

  ('ap-server-q3', '稼働率とシステムの信頼性',
   'あるサーバーのMTBF（平均故障間隔）は180時間、MTTR（平均修復時間）は20時間である。このサーバーの稼働率は何％か。',
   NULL::text,
   '["90%", "80%", "20%", "9%"]',
   0, '[0]', 'single',
   '{"asked":"MTBFとMTTRの数値から稼働率を計算する問題。","why_asked":"稼働率＝MTBF÷(MTBF+MTTR)という式を、意味を理解した上で正しく適用できるかを問う定番の計算問題。","kid":"稼働率は「動いている時間の割合」。1周期（動いている時間＋直している時間）のうち、動いている時間がどれくらいの割合を占めるかを計算する。","eg":"たとえるなら、200日のうち180日元気に働いて20日入院していた人の「元気だった割合」を計算するイメージ。180÷200＝90%。","terms":[["稼働率","システムが正常に動いている時間の割合。稼働率＝MTBF÷(MTBF+MTTR)で求める"]],"calc":{"steps":["問題: MTBF=180時間、MTTR=20時間のときの稼働率を求める","ステップ1: 「動いている時間＋直している時間」の合計を求める。180＋20＝200時間","ステップ2: そのうち動いている時間（MTBF）の割合を計算する。180÷200＝0.9","ステップ3: 割合を％に直す。0.9×100＝90%","答え: 稼働率は90%"],"formula":"稼働率 = MTBF ÷ (MTBF + MTTR) = 180 ÷ (180+20) = 180÷200 = 0.9 = 90%"},"think":"稼働率は「全体の時間のうち、動いていた時間の割合」という定義に忠実に計算すればよい。全体＝MTBF＋MTTR、動いていた時間＝MTBFなので、その比を取るだけ。","vs":"MTBFだけを見て「180%」のように誤答しないこと。MTBFは時間そのものであり、割合ではない。稼働率にするにはMTTRと合わせて比を取る必要がある。","opt":["正解。180÷(180+20)＝180÷200＝0.9＝90%。","180÷(180+20)を計算する際にMTTRを引く方向で計算してしまった値（180-20=160ではなく、200-180×0.2のような誤算をした場合などに出やすい値）。","20÷200のように、MTTR側の割合を答えてしまった値。これは「止まっていた時間の割合」であり、稼働率ではない。","20÷(180+20)を100倍しないなど、桁の処理を誤った値。"]}'),

  ('ap-server-q4', '稼働率とシステムの信頼性',
   '稼働率0.95のサーバーAと稼働率0.8のサーバーBを直列につないだシステム全体の稼働率は何％か。',
   NULL::text,
   '["76%", "87.5%", "99%", "15%"]',
   0, '[0]', 'single',
   '{"asked":"直列に接続された2つの機器の全体稼働率を計算する問題。","why_asked":"直列システムの稼働率は「両方とも動いている必要がある」という条件から掛け算で求める、という基本パターンの確認。","kid":"直列は「両方とも動いていないと全体が止まる」つなぎ方。だから全体の稼働率は、それぞれの稼働率を掛け算して求める。","eg":"たとえるなら、2つの改札を両方通らないと駅に入れない構造。片方の改札が閉まっていたら、もう片方が開いていても意味がない。","terms":[["直列","複数の機器を一本道でつなぎ、すべてが正常でないと全体が動かない構成"]],"calc":{"steps":["問題: 稼働率0.95のAと稼働率0.8のBを直列につないだときの全体の稼働率を求める","ステップ1: 直列は「両方とも動いている」ことが必要なので、それぞれの稼働率を掛け算する","ステップ2: 0.95×0.8を計算する。0.95×0.8＝0.76","ステップ3: 割合を％に直す。0.76×100＝76%","答え: 全体の稼働率は76%"],"formula":"直列の稼働率 = A × B = 0.95 × 0.8 = 0.76 = 76%"},"think":"直列は「AND条件」（AもBも両方動いている必要がある）なので、確率の掛け算になる。掛け算をすると必ずどちらか単体より小さい値になる、という感覚も持っておくとよい。","vs":"足し算(0.95+0.8-1のような式)や平均((0.95+0.8)÷2)と混同しないこと。直列は掛け算、これが崩れると全体が動かないという構造をそのまま式にしたもの。","opt":["正解。0.95×0.8＝0.76＝76%。","(0.95+0.8)÷2で平均を取ってしまった値。直列の稼働率は平均ではなく掛け算で求める。","1-(1-0.95)×(1-0.8)のように、並列の計算式を誤って使ってしまった場合に近い値。","0.95-0.8のように引き算をしてしまった場合の値。稼働率どうしを引き算する意味はない。"]}'),

  ('ap-server-q5', '稼働率とシステムの信頼性',
   '稼働率0.9のサーバーAと稼働率0.7のサーバーBを並列につないだシステム全体の稼働率は何％か。',
   NULL::text,
   '["97%", "63%", "80%", "16%"]',
   0, '[0]', 'single',
   '{"asked":"並列に接続された2つの機器の全体稼働率を計算する問題。","why_asked":"並列システムの稼働率は「両方同時に止まる確率」を1から引いて求める、という直列とは逆の考え方を確認する。","kid":"並列は「どちらか片方が動いていれば全体は動く」つなぎ方。だから、全体が止まるのは「両方とも同時に止まったとき」だけ。その「両方同時に止まる確率」を1から引くと稼働率になる。","eg":"たとえるなら、2つの入口がある建物。片方の入口が閉まっていても、もう片方が開いていれば中に入れる。両方の入口が同時に閉まったときだけ、建物に入れなくなる。","terms":[["並列","複数の機器を横に並べ、どれか1つでも動いていれば全体が動く構成"]],"calc":{"steps":["問題: 稼働率0.9のAと稼働率0.7のBを並列につないだときの全体の稼働率を求める","ステップ1: まず「止まっている確率」を求める。Aが止まっている確率＝1-0.9＝0.1、Bが止まっている確率＝1-0.7＝0.3","ステップ2: 「両方同時に止まる確率」を計算する。0.1×0.3＝0.03","ステップ3: 「両方同時に止まる確率」を1から引くと、全体が動いている確率になる。1-0.03＝0.97","答え: 全体の稼働率は97%"],"formula":"並列の稼働率 = 1 - (1-A) × (1-B) = 1 - (1-0.9)×(1-0.7) = 1 - 0.1×0.3 = 1-0.03 = 0.97 = 97%"},"think":"並列は「ORの条件」（AかBのどちらかが動いていればよい）なので、直接足し算や掛け算では求められない。「両方とも止まる」という一番厳しい状況の確率を先に求め、それ以外のケース（全体は動いている）の確率として1から引く、という2段構えの計算になる。","vs":"直列の掛け算(0.9×0.7=0.63)と混同しやすいが、それは「両方とも動いている」場合の確率であり、並列で問われている「どちらか一方でも動いていればよい」場合の確率とは意味が違う。","opt":["正解。1-(1-0.9)×(1-0.7)＝1-0.1×0.3＝1-0.03＝0.97＝97%。","0.9×0.7を計算した値。これは直列（両方とも動いている必要がある場合）の稼働率であり、並列の計算式ではない。","(0.9+0.7)÷2のように平均を取ってしまった値。並列の稼働率は平均では求められない。","0.1×0.3の「両方同時に止まる確率」自体を、稼働率だと勘違いして答えてしまった値。"]}'),

  ('ap-server-q6', '稼働率とシステムの信頼性',
   '同じ性能のサーバーを2台用意するとき、直列に接続する場合と並列に接続する場合を比べると、システム全体の稼働率について一般的に言えることはどれか。',
   NULL::text,
   '["並列にした方が、システム全体の稼働率は高くなる", "直列にした方が、システム全体の稼働率は高くなる", "つなぎ方によらず、全体の稼働率は常に同じになる", "台数を増やすと、つなぎ方によらず稼働率は必ず下がる"]',
   0, '[0]', 'single',
   '{"asked":"直列と並列で全体の稼働率がどう変わるかという一般的な傾向を問う問題。","why_asked":"個別の計算だけでなく、「なぜ冗長化（サーバーを並列に増やす）がシステムの信頼性を高めるのか」という設計の意図まで理解しているかを問う。","kid":"直列は「両方とも動いていないとダメ」なので、台数を増やすほど条件が厳しくなり稼働率は下がっていく。並列は「どちらか動いていればOK」なので、台数を増やすほど「全部同時に止まる」確率が下がり、稼働率は上がっていく。","eg":"たとえるなら、直列は「両方の橋を渡らないと目的地に着けない」ルート。橋が増えるほど、どこかで通れなくなるリスクが増える。並列は「どちらの橋を渡ってもいい」ルート。橋が増えるほど、両方同時に通れなくなる可能性は下がる。","terms":[["冗長化","同じ機能を持つ機器を複数用意し、1台が故障しても全体が止まらないようにする設計"]],"think":"直列は稼働率どうしを掛け算するので、1未満の数を掛け合わせるほど値は小さくなる（稼働率は下がる）。並列は「両方同時に止まる確率」を掛け算してから1から引くので、確率が掛け合わさるほど「両方同時に止まる確率」は小さくなり、結果として稼働率は上がる。この違いが、実務でサーバーを冗長化（並列に増やす）する理由になっている。","vs":"「台数を増やせば増やすほど必ず良くなる」という単純な理解ではなく、「増やし方（直列か並列か）によって効果が正反対になる」という点が試験で問われやすい。","opt":["正解。並列につなぐと「全部同時に止まる」確率が下がるため、台数を増やすほど全体の稼働率は高くなる。","直列につなぐと「1台でも止まれば全体が止まる」ため、台数を増やすほどむしろ全体の稼働率は下がる。","直列と並列では稼働率の計算方法（掛け算か、1から引くか）がまったく異なり、結果も一致しない。","並列に台数を増やす場合は、稼働率はむしろ上がっていくため、この記述は誤り。"]}'),

  ('ap-server-q7', '稼働率とシステムの信頼性',
   '稼働率0.9のサーバーを3台、直列に接続したシステム全体の稼働率は何％か（小数第3位を四捨五入すること）。',
   NULL::text,
   '["72.9%", "90%", "27%", "97%"]',
   0, '[0]', 'single',
   '{"asked":"3台直列のシステムの稼働率を計算する問題。","why_asked":"2台の計算に慣れた後、台数が増えても同じ掛け算の考え方を延長できるかを確認する。","kid":"直列は「全部動いていないとダメ」なので、台数が3台に増えても、それぞれの稼働率を全部掛け算すればよい。","eg":"たとえるなら、3つの改札を順番に全部通らないと駅に入れない構造。改札が1つ増えるごとに、全部通り抜けられる確率は下がっていく。","terms":[["直列","すべての機器が正常でないと全体が動かない構成。台数が増えるほど条件は厳しくなる"]],"calc":{"steps":["問題: 稼働率0.9のサーバーを3台、直列につないだときの全体の稼働率を求める","ステップ1: 直列は全部の稼働率を掛け算する。0.9×0.9×0.9を計算する","ステップ2: まず0.9×0.9＝0.81を計算する","ステップ3: 0.81×0.9＝0.729を計算する","ステップ4: 割合を％に直し、小数第3位を四捨五入する。0.729×100＝72.9%","答え: 全体の稼働率は72.9%"],"formula":"直列の稼働率 = 0.9 × 0.9 × 0.9 = 0.729 = 72.9%"},"think":"直列は2台のときと同じ掛け算の考え方を、台数分だけ繰り返すだけでよい。台数が増えるほど1未満の数を何度も掛けることになるため、全体の稼働率はどんどん下がっていく。","vs":"1台のときの稼働率0.9（90%）をそのまま答えないこと。台数が増えても稼働率が変わらないのは、並列で考えたときの直感と混同しやすい。直列では台数が増えるほど不利になる。","opt":["正解。0.9×0.9×0.9＝0.729＝72.9%。","1台あたりの稼働率0.9(90%)をそのまま答えてしまった値。3台直列にした影響が反映されていない。","0.9×0.9×0.9ではなく0.9×0.3のような誤った掛け算をした場合に近い値。","並列で3台つないだ場合に近い高い稼働率の値で、直列の計算結果ではない。"]}'),

  ('ap-server-q8', 'RAIDの仕組みと計算',
   '複数のディスクにデータを分散して書き込むことで読み書きを高速化するが、冗長性（壊れたときの保険）は持たないRAIDの構成はどれか。',
   NULL::text,
   '["RAID0（ストライピング）", "RAID1（ミラーリング）", "RAID5（パリティ分散）", "RAID6（二重パリティ）"]',
   0, '[0]', 'single',
   '{"asked":"データを分散して高速化するが冗長性を持たないRAID構成を選ぶ問題。","why_asked":"RAIDの中で唯一「冗長性が無い」構成であるRAID0の位置づけを、他のRAIDと区別して理解しているかを問う。","kid":"RAID0は、1つのデータを複数のディスクに分けて同時に書き込むことで速く読み書きできるようにする仕組み。ただし、コピーを取っているわけではないので、どれか1台が壊れると全部のデータが読めなくなる。","eg":"たとえるなら、1冊の本を10人で1ページずつ分担して同時に書き写す作業。速く終わるけど、1人でも欠けるとその人の担当ページだけが永遠に欠けたままになる。","terms":[["ストライピング","データを複数のディスクに分割して同時に書き込むことで速度を上げる仕組み"],["冗長性","一部が壊れても全体が失われないようにする「保険」のような仕組み"]],"think":"RAIDの中で「速さ」だけを追求し「保険（冗長性）」を持たないのがRAID0という位置づけをまず押さえる。他のRAID（1,5,6）はすべて何らかの形でコピーやパリティという保険を持つ。","vs":"RAID1（ミラーリング）と混同しやすいが、RAID1は同じデータを2台に複製する「保険重視」の構成で、RAID0の「速度重視・保険なし」とは正反対の性格を持つ。","opt":["正解。データを分散して速度を上げるが、コピーやパリティのような保険を持たない構成。","RAID1は同じデータを複数のディスクに複製する構成で、速度よりも保険（冗長性）を重視する。","RAID5はデータとパリティ（誤り訂正用の情報）を分散して持つ構成で、1台の故障に耐えられる保険を持つ。","RAID6はRAID5をさらに強化し、2台同時の故障にも耐えられるよう二重のパリティを持つ構成。"]}'),

  ('ap-server-q9', 'RAIDの仕組みと計算',
   '同じデータを複数のディスクに複製して書き込むことで、1台が故障してももう1台からデータを守れるようにするRAIDの構成はどれか。',
   NULL::text,
   '["RAID1（ミラーリング）", "RAID0（ストライピング）", "RAID5（パリティ分散）", "JBOD（単純な連結）"]',
   0, '[0]', 'single',
   '{"asked":"同じデータを複数ディスクに複製して保護するRAID構成を選ぶ問題。","why_asked":"RAID1の「複製による保護」という仕組みを、パリティ方式（RAID5）と区別して理解しているかを問う。","kid":"RAID1は、まったく同じデータを2台のディスクに両方書き込む仕組み。片方が壊れても、もう片方にそっくりそのままのコピーが残っているので安心。","eg":"たとえるなら、大事な書類のコピーをもう1部作って別の引き出しにしまっておくイメージ。片方の引き出しが火事になっても、もう片方は無事。","terms":[["ミラーリング","同じデータを複数のディスクにそっくりそのまま複製して保存する仕組み"]],"think":"RAID1は「そっくりそのままのコピーを持つ」というシンプルな保険の仕組み。実効容量が半分になる代わりに、仕組みが単純で復旧も分かりやすいという特徴がある。","vs":"RAID5と混同しやすいが、RAID5は「元のデータ＋計算で作った誤り訂正情報（パリティ）」という間接的な保険であり、RAID1の「そっくりそのままのコピー」という直接的な保険とは仕組みが違う。","opt":["正解。同じデータをそっくりそのまま複数のディスクに複製して保護する構成。","RAID0はデータを分散して速度を上げる構成で、複製による保護の仕組みは持たない。","RAID5はデータとパリティ（誤り訂正用の情報）を分散して持つ構成で、そっくりそのままのコピーを作る仕組みとは異なる。","JBODは複数のディスクを単純につなげて1つの大きな領域として扱う方式で、速度向上も保護もRAIDのような仕組みでは行わない。"]}'),

  ('ap-server-q10', 'RAIDの仕組みと計算',
   'RAID5は、元のデータに加えて「パリティ」と呼ばれる誤り訂正用の情報を各ディスクに分散して持たせる。この仕組みによって、RAID5が実現できることとして最も適切なものはどれか。',
   NULL::text,
   '["ディスクが1台故障しても、残りのディスクとパリティからデータを復元できる", "ディスクが何台故障しても、必ずすべてのデータを復元できる", "パリティによってデータの読み書きの速度だけが向上し、故障には対応できない", "パリティは暗号化のための情報であり、故障対策とは関係がない"]',
   0, '[0]', 'single',
   '{"asked":"RAID5のパリティが実現する耐障害性の範囲を問う問題。","why_asked":"「パリティがあれば絶対安全」という誤解と、「RAID5は1台の故障までしか耐えられない」という正確な理解の違いを区別させる。","kid":"パリティは「もし1台分のデータが消えても、残りのデータとパリティを使って元通りに計算し直せる」ための情報。ただし、これは1台分の穴埋めしかできない仕組みなので、2台同時に壊れると計算し直せなくなる。","eg":"たとえるなら、3人でクイズの合計点を覚えていて、そのうち1人の点数を忘れても残り2人の点数と合計点から逆算できる、という仕組み。でも2人同時に忘れたら、もう逆算できない。","terms":[["パリティ","元のデータから計算で作られる、誤り訂正用の情報。1台分の欠損を穴埋めできる"]],"think":"パリティは「欠けた1台分を、残りの情報から計算で復元する」ための仕組みであり、無限に故障に耐えられる魔法ではない。RAID5は同時に2台以上壊れると復元できなくなる、という限界を持つ。","vs":"「何台壊れても大丈夫」という誤解に注意。この上位互換であるRAID6は二重のパリティを持ち、2台同時の故障まで耐えられるように設計されている。RAID5とRAID6の耐障害性の違いは定番の出題ポイント。","opt":["正解。パリティによって1台分の故障までは、残りの情報から計算で復元できる。","RAID5は1台の故障までしか耐えられず、2台以上同時に故障するとデータは復元できない。","パリティは速度向上だけでなく、1台故障時のデータ復元という耐障害性の目的で持たせている情報である。","パリティは誤り訂正のための情報であり、暗号化（第三者に読めなくする）とは別の目的の仕組みである。"]}'),

  ('ap-server-q11', 'RAIDの仕組みと計算',
   '容量500GBのディスクを2台用意し、RAID1（ミラーリング）を構成した。このとき実際にデータの保存に使える容量（実効容量）は何GBか。',
   NULL::text,
   '["500GB", "1000GB", "250GB", "750GB"]',
   0, '[0]', 'single',
   '{"asked":"RAID1構成時の実効容量を計算する問題。","why_asked":"「ディスクを2台使っているから容量は2倍になる」という誤解を正し、RAID1は容量よりも保護を優先する構成であることを確認する。","kid":"RAID1は同じデータを2台にコピーする仕組みなので、実際に保存できる量は「1台分」しかない。もう1台は保険用のコピーとして使われている。","eg":"たとえるなら、500ページのノートを2冊用意して、まったく同じ内容を両方に書き写す。使える情報量は500ページ分のままで、2冊分の1000ページ分の情報が入るわけではない。","terms":[["実効容量","実際にデータの保存に使える容量。RAIDの構成によって全体の容量より小さくなることがある"]],"calc":{"steps":["問題: 500GBのディスクを2台使ってRAID1を組んだときの実効容量を求める","ステップ1: RAID1は同じデータを2台に複製する仕組みだと確認する","ステップ2: 2台のうち1台分は「コピー用」に使われるため、実際に使える容量は1台分だけになる","ステップ3: 500GB×1＝500GB","答え: 実効容量は500GB"],"formula":"RAID1の実効容量 = ディスク1台分の容量 = 500GB（台数を増やしても、ペアが1組ならこの値のまま）"},"think":"RAID1は「容量を増やす」ためではなく「同じデータの保険を持つ」ための構成だと理解すれば、実効容量が1台分にとどまることは自然に納得できる。容量ではなく安全性を買っている、という発想。","vs":"RAID0と混同しやすい。RAID0はディスクを分散して使うため合計容量（この場合1000GB）がそのまま使えるが、RAID1は保険のために容量を犠牲にしている。","opt":["正解。同じデータを2台に複製する仕組みなので、実効容量はディスク1台分の500GBになる。","2台分の容量をそのまま合計してしまった値。これはRAID0（分散構成）の実効容量の考え方であり、RAID1には当てはまらない。","500GBを半分にしてしまった値。RAID1は台数を増やしても、1台分の容量はそのまま使える。","500GBの1.5倍のような値で、RAID1の実効容量の計算根拠にはならない。"]}'),

  ('ap-server-q12', 'RAIDの仕組みと計算',
   '容量250GBのディスクを4台用意し、RAID5（パリティ分散）を構成した。このとき実際にデータの保存に使える容量（実効容量）は何GBか。',
   NULL::text,
   '["750GB", "1000GB", "500GB", "250GB"]',
   0, '[0]', 'single',
   '{"asked":"RAID5構成時の実効容量を計算する問題。","why_asked":"「実効容量＝全体からパリティ1台分を引いた分」という考え方を、実際の数値で計算できるかを確認する。","kid":"RAID5は、パリティ（誤り訂正用の情報）を各ディスクに分散して持つけれど、その合計量はちょうどディスク1台分に相当する。だから、4台のうち実質1台分がパリティ用に使われ、残り3台分がデータの保存に使える。","eg":"たとえるなら、4人でお金を出し合って何かを買うとき、そのうち1人分の金額はいつも「もしもの時の積立」に回すルール。実際に買い物に使えるのは残り3人分の金額、というイメージ。","terms":[["実効容量","実際にデータの保存に使える容量。RAID5では全体からパリティ1台分を引いた量になる"]],"calc":{"steps":["問題: 250GBのディスクを4台使ってRAID5を組んだときの実効容量を求める","ステップ1: RAID5の実効容量は「台数-1」台分になる、というルールを確認する","ステップ2: 台数は4台なので、4-1＝3台分がデータ保存に使える","ステップ3: 3台×250GB＝750GB","答え: 実効容量は750GB"],"formula":"RAID5の実効容量 = (台数-1) × 1台あたりの容量 = (4-1) × 250GB = 3 × 250GB = 750GB"},"think":"RAID5は「全体の容量」から「パリティ1台分の容量」を引いたものが実効容量になる、という式をそのまま使えばよい。パリティは特定の1台に固定されているわけではなく全ディスクに分散しているが、容量の計算上は「1台分が保険に消える」と考えてよい。","vs":"RAID1の「1台分だけ使える」という計算と混同しやすいが、RAID5は台数が増えるほど実効容量も増えていく（無駄になるのは常に1台分だけ）という点が異なる。","opt":["正解。(4-1)×250GB＝3×250GB＝750GB。","4台分をそのまま合計してしまった値(4×250GB)。パリティ用に1台分が使われることが反映されていない。","RAID1のように2台分をペアとして扱ってしまった場合に近い値。RAID5の計算とは仕組みが異なる。","1台分の容量をそのまま答えてしまった値。4台構成であることが反映されていない。"]}'),

  ('ap-server-q13', 'RAIDの仕組みと計算',
   '容量250GBのディスクを4台用意する場合、RAID1（2組のミラーリングとして構成）とRAID5で構成したときの実効容量を比べると、どちらが大きいか。',
   NULL::text,
   '["RAID5の方が実効容量が大きい", "RAID1の方が実効容量が大きい", "どちらも同じ実効容量になる", "台数が同じなら比較できない"]',
   0, '[0]', 'single',
   '{"asked":"同じディスク構成でRAID1とRAID5の実効容量を比較する問題。","why_asked":"それぞれの実効容量の計算式を正しく使い、実際に数値で比較できるかという応用力を問う。","kid":"4台を2組のペアにしてRAID1を組むと、実際に使えるのは2台分だけ。RAID5なら4台のうち3台分が使える。だから同じ4台でも、RAID5の方が使える容量は多くなる。","eg":"たとえるなら、4人分の荷物を2人1組でお互いに同じ荷物を持ち合う(RAID1)より、4人で1人分だけを「もしもの予備」に回す(RAID5)方が、実際に運べる荷物の量は多くなる、というイメージ。","terms":[["RAID1の実効容量","台数の半分（ペアの数）×1台分の容量"],["RAID5の実効容量","(台数-1)×1台分の容量"]],"calc":{"steps":["問題: 250GBのディスク4台で、RAID1(2組のミラー)とRAID5それぞれの実効容量を求めて比較する","ステップ1: RAID1は4台を2組のペアにするので、実効容量は2台分。2×250GB＝500GB","ステップ2: RAID5は4台のうち1台分がパリティに使われるので、実効容量は3台分。3×250GB＝750GB","ステップ3: 500GBと750GBを比較する。750GB＞500GBなのでRAID5の方が大きい","答え: RAID5の方が実効容量が大きい（750GB＞500GB）"],"formula":"RAID1: 2×250GB=500GB / RAID5: (4-1)×250GB=750GB → RAID5が750GBで上回る"},"think":"RAID1はペアごとに1台分が丸ごと保険用に消費されるのに対し、RAID5は全体でパリティ1台分だけが保険用に消費される。台数が多いほど、この差はさらに開いていく。","vs":"「保険の手厚さ」で比べるとRAID1の方が(同時に複数台故障しても片方のペアが残っていれば安全な場合がある等)有利な場面もあるが、この問題で問われている「実効容量」という観点だけで見ればRAID5の方が効率が良い。","opt":["正解。RAID1は500GB、RAID5は750GBとなり、RAID5の方が実効容量が大きい。","RAID1は2組のペアに分かれる分、保険用に消費される容量が多く、実効容量はRAID5より小さくなる。","RAID1は500GB、RAID5は750GBとなり、同じ容量にはならない。","台数と1台あたりの容量が分かっていれば、それぞれの計算式で実効容量を求めて比較できる。"]}'),

  ('ap-server-q14', 'RAIDの仕組みと計算',
   'RAID0はデータの読み書きを高速化できるが、実運用でRAID0だけを単独で使うことが敬遠されがちな理由として最も適切なものはどれか。',
   NULL::text,
   '["1台でも故障するとデータ全体が失われるため、バックアップなどの対策と併用しないと危険", "RAID0は読み書きの速度がRAID1やRAID5より遅いため", "RAID0はディスクを1台しか使えないという制約があるため", "RAID0は暗号化ができず、セキュリティ上の弱点になるため"]',
   0, '[0]', 'single',
   '{"asked":"RAID0が実運用で単独使用を敬遠されがちな理由を問う問題。","why_asked":"「速い＝良い構成」という単純な理解ではなく、速度と引き換えに失っているもの（冗長性）を理解しているかを問う。","kid":"RAID0はデータを分散して保存するので、1台でも壊れると、そのディスクが担当していた分だけデータが虫食い状態になり、結局全部のデータが読めなくなってしまう。速さと引き換えに「保険」を持っていない構成だから。","eg":"たとえるなら、1冊の本を10人で分担して書いた原稿。1人分のページが失われると、本全体が完成しないのと同じ。","terms":[["冗長性","一部が壊れても全体が失われないようにする仕組み。RAID0はこれを持たない"]],"think":"RAID0は「速さ」を追求するあまり「保険（冗長性）」を持たないという設計上のトレードオフを持つ。だから実運用では、RAID0を使う場合でも別途バックアップを取るなど、他の対策と組み合わせるのが一般的とされる。","vs":"「RAID0は遅い」という誤解に注意。RAID0はむしろRAIDの中でも読み書きが速い部類に入る構成であり、問題点は速度ではなく耐障害性の低さにある。","opt":["正解。1台でも故障すると全体のデータが失われるため、バックアップ等の対策なしでは危険視される。","RAID0はデータを分散して同時に読み書きできるため、むしろRAIDの中でも高速な部類に入る構成である。","RAID0は複数台のディスクを組み合わせて構成するのが前提であり、1台しか使えないという制約はない。","RAID0は暗号化の有無とは無関係な仕組みであり、暗号化はRAIDとは別のレイヤーで行われる。"]}'),

  ('ap-server-q15', '負荷分散と高可用性設計',
   '複数のサーバーに処理を振り分け、1台あたりの負荷を減らしたり、1台が故障しても他のサーバーで処理を続けられるようにする装置・仕組みを何というか。',
   NULL::text,
   '["ロードバランサ", "ファイアウォール", "プロキシサーバー", "DNSサーバー"]',
   0, '[0]', 'single',
   '{"asked":"複数サーバーへ処理を振り分ける装置・仕組みの名前を問う問題。","why_asked":"負荷分散と高可用性設計の入口となる基本用語。他のネットワーク機器と役割を混同しないかを確認する。","kid":"ロードバランサは「仕事の振り分け係」。お客さんからのリクエストを、空いているサーバーに順番に割り振っていく役割を持つ。1台が壊れても、残りのサーバーに振り分ければサービスは止まらない。","eg":"たとえるなら、コンビニのレジで「空いているレジへどうぞ」と案内する店員さん。お客さんが1つのレジに集中しないように、全体をうまく分配してくれる。","terms":[["ロードバランサ","複数のサーバーに処理（負荷）を振り分ける装置・仕組み。Load Balancerの略で、直訳は「負荷・バランスを取る人」"]],"think":"「負荷を分散する」「1台故障しても他が肩代わりできる」という2つの効果が、そのままロードバランサの存在意義になっている。","vs":"ファイアウォールと混同しやすいが、ファイアウォールは不正な通信を遮断する「門番」の役割であり、処理を振り分ける役割ではない。","opt":["正解。複数のサーバーに処理を振り分け、負荷分散と高可用性の両方を実現する装置・仕組み。","ファイアウォールは通信の中身を検査して不正なものを遮断するセキュリティ機器で、処理の振り分けが役割ではない。","プロキシサーバーはクライアントの代わりに通信を中継する仕組みで、複数サーバーへの負荷分散が主目的ではない。","DNSサーバーはドメイン名からIPアドレスを調べる仕組みで、処理の振り分け自体を行う装置ではない。"]}'),

  ('ap-server-q16', '負荷分散と高可用性設計',
   '複数台のサーバーをすべて稼働させ、それぞれが同時にリクエストを処理する構成を何というか。',
   NULL::text,
   '["Active-Active構成", "Active-Standby構成", "シングル構成", "コールドスタンバイ構成"]',
   0, '[0]', 'single',
   '{"asked":"複数台すべてが同時に稼働する冗長構成の名前を問う問題。","why_asked":"Active-StandbyとActive-Activeという2つの代表的な冗長構成の違いを区別できるかを問う。","kid":"Active-Activeは、用意したサーバー全員が「現役（Active）」として同時に働いている状態。1台に何かあっても、残りのメンバーがそのまま働き続けられる。","eg":"たとえるなら、レジを2台とも開けて、両方のレジでお客さんを同時にさばいているコンビニ。1台が故障しても、もう1台がそのまま営業を続けられる。","terms":[["Active-Active","複数のサーバーがすべて同時に稼働し、処理を分担する構成"],["Active-Standby","普段は1台だけが稼働し、もう1台は待機しておいて、故障時に切り替える構成"]],"think":"「全員が働いているか、一部は待機しているか」という点でActive-ActiveとActive-Standbyを区別する。Active-Activeは負荷分散の効果も同時に得られるのが特徴。","vs":"Active-Standbyと混同しやすいが、Active-Standbyは待機系(Standby)が普段は仕事をしていない点が違う。Active-Activeは待機系そのものが存在せず、全員が現役で働く。","opt":["正解。複数のサーバーがすべて同時に稼働し、処理を分担する構成。","Active-Standbyは1台だけが稼働し、もう1台は普段待機しておく構成で、全員が同時に働くわけではない。","シングル構成はサーバーが1台しかない構成で、冗長性そのものを持たない。","コールドスタンバイは、故障時に電源を入れて起動するところから始める、より復旧に時間がかかる待機方式。"]}'),

  ('ap-server-q17', '負荷分散と高可用性設計',
   '普段は1台のサーバーだけが処理を担当し、もう1台は電源を入れたまま待機させておき、故障時にすぐ切り替えられるようにしておく構成を何というか。',
   NULL::text,
   '["Active-Standby構成", "Active-Active構成", "ロードバランシング構成", "クラウドバースト構成"]',
   0, '[0]', 'single',
   '{"asked":"1台が待機系として控えている冗長構成の名前を問う問題。","why_asked":"Active-Activeとの対比で、待機系(Standby)の考え方を正確に理解しているかを問う。","kid":"Active-Standbyは、普段は1台だけが実際に働いていて(Active)、もう1台は電源を入れたまま何もせず待機している(Standby)状態。働いている方が壊れたら、待機していた方にすぐバトンタッチする。","eg":"たとえるなら、正選手が試合に出ている間、控え選手はベンチでいつでも出られるように準備している状態。正選手が怪我をしたら、すぐに控え選手が試合に出る。","terms":[["Standby","「待機」という意味の英単語。普段は処理を行わず、切り替えに備えて準備している状態"]],"think":"Active-Standbyは「普段は片方しか働いていない」という点でActive-Activeと対照的。切り替えの速さと、普段のリソースの使い方（待機系は普段仕事をしない分もったいない、という見方もある）がトレードオフになる。","vs":"Active-Activeと混同しやすいが、Active-Activeは両方が同時に働いて負荷分散の効果も得られるのに対し、Active-Standbyは待機系が普段まったく処理を担当しない点が違う。","opt":["正解。1台だけが稼働し、もう1台は待機して故障時に切り替える構成。","Active-Activeは複数のサーバーが同時に稼働し、負荷を分担する構成で、片方だけが働くわけではない。","ロードバランシングは処理を複数のサーバーに振り分ける仕組み全般を指す言葉で、待機系という概念とは別の話。","クラウドバーストは、普段はオンプレミスで処理し、負荷が急増したときだけクラウドのリソースを一時的に使う構成のこと。"]}'),

  ('ap-server-q18', '負荷分散と高可用性設計',
   'システムの中で「そこが壊れるとシステム全体が止まってしまう箇所」を何というか。',
   NULL::text,
   '["SPOF（単一障害点）", "MTBF（平均故障間隔）", "ボトルネック", "デッドロック"]',
   0, '[0]', 'single',
   '{"asked":"システム全体を止めてしまう1点を表す用語を問う問題。","why_asked":"高可用性設計の目的（SPOFを無くすこと）を理解する土台となる基本用語。","kid":"SPOFは、そこだけが壊れると全体が止まってしまう「弱点」のこと。冗長化（同じ機能を持つ機器を複数用意すること）は、このSPOFを無くすために行う。","eg":"たとえるなら、1本足の椅子。その足が折れたら、椅子全体が倒れてしまう。足を複数本にしておけば、1本折れても倒れない。","terms":[["SPOF","Single Point of Failureの略。直訳は「単一の・故障・点」。そこが壊れるとシステム全体が止まる箇所"]],"think":"高可用性設計の基本方針は「SPOFを見つけて、そこを冗長化する（複数用意する）」こと。ロードバランサ自体やネットワーク機器がSPOFになっていないかも、実務では注意深く確認される。","vs":"ボトルネックと混同しやすいが、ボトルネックは「処理速度が遅くなる箇所」を指し、SPOFは「そこが壊れると全体が止まる箇所」を指す。速度の問題と、停止の問題は別の観点。","opt":["正解。そこが壊れるとシステム全体が止まってしまう箇所を指す用語。","MTBFは故障してから次の故障までの平均間隔を表す時間の指標で、箇所を指す言葉ではない。","ボトルネックは処理速度を遅くしている原因となる箇所を指す言葉で、必ずしも全体を停止させるとは限らない。","デッドロックは複数の処理がお互いに相手を待ち続けて先に進めなくなる状態を指す言葉で、単一の箇所を指すものではない。"]}'),

  ('ap-server-q19', '負荷分散と高可用性設計',
   '同じ役割を持つサーバーを複数台まとめて1つのシステムのように動かし、負荷分散や高可用性を実現する仕組みを何というか。',
   NULL::text,
   '["クラスタリング", "パーティショニング", "レプリケーション", "シャーディング"]',
   0, '[0]', 'single',
   '{"asked":"複数台のサーバーをまとめて1つのシステムとして動かす仕組みの名前を問う問題。","why_asked":"ロードバランサ・Active-Active・SPOFといった個別の概念を束ねる、より大きな枠組みの用語を確認する。","kid":"クラスタリングは、複数台のサーバーを「1つのチーム」としてまとめて動かす仕組み。外から見ると、まるで1台の大きなサーバーが動いているように見える。","eg":"たとえるなら、複数の店員が力を合わせて1つの大きな厨房のように連携して料理を作るレストラン。お客さんから見ると、まるで1つの厨房が動いているように見える。","terms":[["クラスタ","同じ役割を持つ複数のサーバーをまとめた集団。Clusterは「房・集団」という意味"]],"think":"ロードバランサによる負荷分散も、Active-Standbyによる冗長化も、広い意味では「クラスタリング」という仕組みの一部として実現されることが多い。","vs":"レプリケーション（データの複製をリアルタイムで作り続ける仕組み）と混同しやすいが、クラスタリングはサーバー群全体の連携の仕組みを指し、レプリケーションはその中でデータをどう同期するかという一部分の話。","opt":["正解。複数台のサーバーをまとめて1つのシステムのように動かす仕組み。","パーティショニングはデータを複数の領域に分割して管理する手法で、サーバー全体をまとめる話とは別の観点。","レプリケーションはデータの複製をリアルタイムで作り続ける仕組みで、クラスタリングの一部として使われることはあるが同義ではない。","シャーディングはデータを複数のサーバーに分割して分散配置する手法で、主にデータベースの規模拡張で使われる。"]}'),

  ('ap-server-q20', '負荷分散と高可用性設計',
   'Active-Active構成とActive-Standby構成を比べたとき、Active-Active構成に特有の利点として最も適切なものはどれか。',
   NULL::text,
   '["普段から全台が処理を分担するため、負荷分散の効果も同時に得られる", "構成がシンプルになり、切り替えの仕組みが一切不要になる", "待機系を用意する必要がないため、必ず1台だけで運用できる", "故障時にデータが失われる可能性が完全になくなる"]',
   0, '[0]', 'single',
   '{"asked":"Active-Active構成に特有の利点を問う問題。","why_asked":"Active-Standbyとの違いを「利点」という切り口で整理し、単なる用語の暗記でなく設計上の意味を理解しているかを問う。","kid":"Active-Activeは全員が普段から働いているので、故障対策になるだけでなく、みんなで仕事を分け合うことで1人あたりの負担も減らせる、という「一石二鳥」の構成。","eg":"たとえるなら、レジを2台とも開けておくと、1台が壊れたときの保険になるだけでなく、普段からお客さんの行列も分散できる、というイメージ。","terms":[["負荷分散","複数のサーバーで処理を分け合い、1台あたりの負担を減らすこと"]],"think":"Active-Standbyの待機系は、普段は処理を担当せず「保険」としてだけ存在する。一方Active-Activeは全台が現役で働くため、保険の役割に加えて普段の負荷分散という実用的な利点も得られる。","vs":"「切り替えの仕組みが不要になる」という誤解に注意。Active-Activeでも1台が故障した際には残りのサーバーへ処理を寄せる仕組みは必要であり、切り替え自体が無くなるわけではない。","opt":["正解。全台が普段から処理を分担するため、故障対策と負荷分散の両方の効果を同時に得られる。","Active-Activeでも、1台故障時に残りへ処理を寄せる仕組みは必要であり、切り替えの仕組みが不要になるわけではない。","Active-Activeは複数台を同時に稼働させる構成であり、1台だけでの運用を前提とした構成ではない。","冗長構成は故障時のサービス停止を防ぐ仕組みであり、データ消失の可能性を完全にゼロにする保証まではしない。"]}'),

  ('ap-server-q21', '負荷分散と高可用性設計',
   'ロードバランサが複数のサーバーへリクエストを振り分ける方法の1つで、順番にサーバーを巡回するように均等に割り振っていく方式を何というか。',
   NULL::text,
   '["ラウンドロビン方式", "ランダム方式", "最小接続数方式", "重み付け方式"]',
   0, '[0]', 'single',
   '{"asked":"順番にサーバーを巡回して振り分ける方式の名前を問う問題。","why_asked":"ロードバランサの代表的な振り分けアルゴリズムを1つ知っておくことで、抽象的な「負荷分散」の理解に具体性を持たせる。","kid":"ラウンドロビン方式は、サーバーA、B、C、また A、B、C…というふうに、順番に均等にリクエストを割り振っていくやり方。誰か1人に集中しないように、順番を回していくイメージ。","eg":"たとえるなら、給食当番を順番に回していくルール。今日はAさん、明日はBさん、その次はCさん、また今日はAさん…というふうに、順番に均等に役割を回していく。","terms":[["ラウンドロビン","「順番に回す」という意味。ロードバランサの振り分け方式の1つで、サーバーを順番に均等に選ぶ"]],"think":"ラウンドロビンは最もシンプルな振り分け方式で、各サーバーの性能や現在の負荷を考慮せず、機械的に順番を回す。サーバーの性能差が大きい場合は、性能に応じて重みを変える「重み付け方式」の方が向くこともある。","vs":"最小接続数方式と混同しやすいが、最小接続数方式は「今、一番処理数が少ないサーバー」を選ぶのに対し、ラウンドロビンは現在の負荷状況を見ずに単純に順番で選ぶ点が違う。","opt":["正解。サーバーを順番に均等に巡回しながら振り分ける方式。","ランダム方式は毎回無作為にサーバーを選ぶ方式で、順番に巡回するわけではない。","最小接続数方式は、その時点で処理中のリクエストが最も少ないサーバーを選ぶ方式で、順番とは無関係に選ぶ。","重み付け方式は、サーバーの性能に応じてあらかじめ割り振る比率を変えておく方式で、均等な順番割り振りとは異なる。"]}'),

  ('ap-server-q22', 'ネットワークプロトコルの基礎',
   'メールを送信するときに使われるプロトコルはどれか。',
   NULL::text,
   '["SMTP", "POP", "IMAP", "FTP"]',
   0, '[0]', 'single',
   '{"asked":"メール送信に使われるプロトコルを選ぶ問題。","why_asked":"メール関連の3つのプロトコル（SMTP/POP/IMAP）の役割分担を問う定番論点の入口。","kid":"SMTPは「メールを送るとき」に使われる仕組み。手紙をポストに投函するようなイメージで、書いたメールをサーバーへ送り出す役割を持つ。","eg":"たとえるなら、SMTPは郵便ポストに手紙を投函する係。書いた手紙（メール）を、次の配達ルートに乗せる役割を担う。","terms":[["SMTP","Simple Mail Transfer Protocolの略。直訳は「単純な・メール・転送・手順」。メールを送信するためのプロトコル"]],"think":"メールのやり取りには「送る」「受け取る」という2つの向きの通信があり、それぞれ別のプロトコルが使われる。送る方向を担当するのがSMTP。","vs":"POP/IMAPと混同しやすいが、POPとIMAPは「メールを受信する」ためのプロトコルで、SMTPの「送信する」役割とは向きが逆。","opt":["正解。メールを送信するために使われるプロトコル。","POPはメールサーバーからメールを受信（ダウンロード）するためのプロトコルで、送信ではなく受信の役割を持つ。","IMAPもメールを受信するためのプロトコルで、サーバー上でメールを管理しながら閲覧する方式を取る。","FTPはファイルを転送するためのプロトコルで、メールの送受信を目的としたものではない。"]}'),

  ('ap-server-q23', 'ネットワークプロトコルの基礎',
   'メールをサーバーからダウンロードして手元の端末に保存し、サーバー側からは基本的に削除するという方式で受信するプロトコルはどれか。',
   NULL::text,
   '["POP", "SMTP", "IMAP", "DHCP"]',
   0, '[0]', 'single',
   '{"asked":"メールをダウンロードして手元に保存する受信方式のプロトコルを選ぶ問題。","why_asked":"POPとIMAPの違い（ダウンロードして削除するか、サーバー上に残すか）という定番の対比を問う。","kid":"POPは、メールをサーバーから自分の端末にダウンロードしてきて、サーバー側からは消してしまう方式。1つの端末でメールを管理することを想定した仕組み。","eg":"たとえるなら、郵便局に届いた手紙を自宅に持ち帰り、郵便局の私書箱は空っぽにするやり方。手紙は自宅にしか残らない。","terms":[["POP","Post Office Protocolの略。直訳は「郵便局・手順」。メールをダウンロードして受信するプロトコル"]],"think":"POPは「ダウンロードしたら元は消える」という性質上、複数の端末（スマホとPCなど）でメールを見たい場合には不便になりやすい。この不便さを解消するのがIMAPという整理で理解するとよい。","vs":"IMAPと混同しやすいが、IMAPはメールをサーバー上に残したまま、複数端末から同じ内容を確認できる方式で、POPの「ダウンロードして削除」とは仕組みが違う。","opt":["正解。メールをダウンロードして手元に保存し、サーバー側からは基本的に削除する受信方式。","SMTPはメールを送信するためのプロトコルで、受信方式を定めるものではない。","IMAPはメールをサーバー上に残したまま複数端末から確認できる受信方式で、POPとは仕組みが異なる。","DHCPはIPアドレスを自動的に割り当てるためのプロトコルで、メールの受信とは無関係。"]}'),

  ('ap-server-q24', 'ネットワークプロトコルの基礎',
   'メールをサーバー上に残したまま、スマートフォンとパソコンなど複数の端末から同じメールボックスの状態を確認できるようにする受信プロトコルはどれか。',
   NULL::text,
   '["IMAP", "POP", "SMTP", "NTP"]',
   0, '[0]', 'single',
   '{"asked":"複数端末で同じメールボックスを確認できる受信プロトコルを選ぶ問題。","why_asked":"POPとの対比で、IMAPが解決している「複数端末での同期」という課題を理解しているかを問う。","kid":"IMAPは、メールをサーバーに置いたままにして、スマホでもパソコンでも同じ状態（既読・未読や振り分けたフォルダなど）を確認できるようにする仕組み。手元にダウンロードして消してしまうPOPとは逆の考え方。","eg":"たとえるなら、私書箱の中の手紙を持ち帰らずに、私書箱そのものをいつでも見に行けるようにしておくイメージ。どの入口から見ても、私書箱の中身は同じ状態。","terms":[["IMAP","Internet Message Access Protocolの略。直訳は「インターネット・メッセージ・アクセス・手順」。メールをサーバー上で管理しながら受信するプロトコル"]],"think":"「メールの実体をどこに置くか」という発想で覚えるとよい。POPは端末側、IMAPはサーバー側に実体を置き続ける、という違いが複数端末での見え方の違いに直結する。","vs":"POPと混同しやすいが、POPはダウンロードしてサーバー側を空にする方式のため、別の端末で見ると同じ状態を再現できない。IMAPはこの弱点を解消する方式として理解する。","opt":["正解。メールをサーバー上に残したまま、複数端末から同じメールボックスの状態を確認できる受信プロトコル。","POPはメールをダウンロードして端末側に保存し、サーバー側からは基本的に削除する方式で、複数端末での同期には向かない。","SMTPはメールを送信するためのプロトコルで、受信・同期の方式を定めるものではない。","NTPは複数の機器の時刻を正確に合わせるためのプロトコルで、メールの受信とは無関係。"]}'),

  ('ap-server-q25', 'ネットワークプロトコルの基礎',
   'パソコンやスマートフォンがネットワークに接続したときに、IPアドレスなどのネットワーク設定を自動的に割り当てる仕組みを何というか。',
   NULL::text,
   '["DHCP", "DNS", "NTP", "SMTP"]',
   0, '[0]', 'single',
   '{"asked":"IPアドレスなどを自動的に割り当てる仕組みの名前を問う問題。","why_asked":"「毎回手動でIPアドレスを設定しなくてよい」という利便性の裏にある仕組みを理解しているかを問う。","kid":"DHCPは、パソコンやスマホがネットワークにつながったときに「あなたにはこのIPアドレスを使ってもらいます」と自動的に割り当ててくれる仕組み。これがないと、みんなが自分でIPアドレスを覚えて手打ちしないといけなくなる。","eg":"たとえるなら、会議室に入った人に自動的に「あなたは3番の席です」と案内してくれる受付係。毎回どの席が空いているか自分で探す必要がない。","terms":[["DHCP","Dynamic Host Configuration Protocolの略。直訳は「動的な・ホスト・設定・手順」。IPアドレスなどのネットワーク設定を自動的に割り当てるプロトコル"]],"think":"DHCPが無いと、ネットワークにつなぐたびに人がIPアドレスを重複しないように手動で割り当てる必要があり、非常に手間がかかる。この「自動割り当て」という利便性がDHCPの存在意義。","vs":"DNSと混同しやすいが、DNSはドメイン名からIPアドレスを調べる「名前解決」の仕組みであり、DHCPの「IPアドレス自体を配る」役割とは別物。","opt":["正解。ネットワークに接続した機器に、IPアドレスなどの設定を自動的に割り当てる仕組み。","DNSはドメイン名（www.example.comなど）からIPアドレスを調べる仕組みで、IPアドレスを配る仕組みではない。","NTPは複数の機器の時刻を正確に合わせるための仕組みで、IPアドレスの割り当てとは無関係。","SMTPはメールを送信するためのプロトコルで、ネットワーク設定の割り当てとは無関係。"]}'),

  ('ap-server-q26', 'ネットワークプロトコルの基礎',
   '複数のコンピュータの時計を、正確な時刻を持つサーバーに合わせて同期させるためのプロトコルはどれか。',
   NULL::text,
   '["NTP", "DHCP", "DNS", "SNMP"]',
   0, '[0]', 'single',
   '{"asked":"複数コンピュータの時刻を同期させるプロトコルを選ぶ問題。","why_asked":"時刻同期という地味だが重要な役割（ログの時刻がずれるとトラブル調査が困難になる等）を担うプロトコルを確認する。","kid":"NTPは、いろんなコンピュータの時計を、正確な時刻を持つ「基準となる時計」に合わせて揃える仕組み。バラバラの時計のままだと、いつ何が起きたのか正確に分からなくなってしまう。","eg":"たとえるなら、学校中の時計を、正確なラジオの時報に合わせて揃えるイメージ。全部の時計が同じ時刻を指していれば、何かがいつ起きたかを混乱なく確認できる。","terms":[["NTP","Network Time Protocolの略。直訳は「ネットワーク・時間・手順」。複数の機器の時刻を同期させるプロトコル"]],"think":"サーバーのログを複数台で突き合わせて調査するようなQA・障害調査の場面では、時刻がずれていると「どちらが先に起きた出来事か」が分からなくなる。時刻を揃えるNTPは、こうしたトラブル調査の前提を支えている。","vs":"DHCPと混同しやすいが、DHCPはIPアドレスなどのネットワーク設定を配る仕組みであり、時刻を合わせる仕組みではない。","opt":["正解。複数の機器の時刻を、正確な時刻を持つサーバーに合わせて同期させるプロトコル。","DHCPはIPアドレスなどのネットワーク設定を自動的に割り当てる仕組みで、時刻の同期とは無関係。","DNSはドメイン名からIPアドレスを調べる仕組みで、時刻の同期とは無関係。","SNMPはネットワーク機器の状態を監視・管理するためのプロトコルで、時刻の同期を主目的とはしていない。"]}'),

  ('ap-server-q27', 'ネットワークプロトコルの基礎',
   'Webサーバーがクライアントに返すHTTPステータスコードのうち、「200番台」が意味する分類として最も適切なものはどれか。',
   NULL::text,
   '["リクエストが正常に成功したことを示す", "サーバー側でエラーが発生したことを示す", "リクエストの内容に誤りがあったことを示す", "別のURLへの転送（リダイレクト）が必要なことを示す"]',
   0, '[0]', 'single',
   '{"asked":"HTTPステータスコードの200番台が意味する分類を問う問題。","why_asked":"ステータスコードの個別番号を丸暗記するのではなく、桁（先頭の数字）ごとの分類という考え方を理解しているかを問う。","kid":"HTTPステータスコードは、先頭の数字によって大まかな意味のグループが決まっている。200番台は「うまくいきました」という成功を伝えるグループ。","eg":"たとえるなら、お店の会計で「200円台の値札は在庫あり、300円台は場所を移動しました、400円台はお客様の注文ミス、500番台はお店側の不手際です」というふうに、値札の百の位でざっくりと状況が分かるようなイメージ。","terms":[["HTTPステータスコード","Webサーバーがリクエストの結果を伝えるための3桁の数字。先頭の数字で大まかな意味が分類されている"]],"think":"すべてのコードを個別に覚えるのではなく、「1xx=情報、2xx=成功、3xx=リダイレクト、4xx=クライアントエラー、5xx=サーバーエラー」という桁の意味の分類を先に押さえるのが実務的。","vs":"400番台と500番台を混同しやすい。400番台は「リクエストした側（クライアント）の誤り」、500番台は「受け取った側（サーバー）の不具合」と、どちら側の問題かで区別する。","opt":["正解。200番台はリクエストが正常に成功したことを示す分類。","サーバー側のエラーを示すのは500番台であり、200番台は成功を示す分類である。","リクエストの内容に誤りがあったことを示すのは400番台であり、200番台は成功を示す分類である。","別のURLへの転送が必要なことを示すのは300番台であり、200番台は成功を示す分類である。"]}'),

  ('ap-server-q28', 'セキュリティの数理と認証',
   '暗号化と復号（元に戻すこと）に同じ1つの鍵を使う暗号方式を何というか。',
   NULL::text,
   '["共通鍵暗号方式", "公開鍵暗号方式", "ハッシュ関数", "デジタル署名"]',
   0, '[0]', 'single',
   '{"asked":"暗号化と復号に同じ鍵を使う方式の名前を問う問題。","why_asked":"公開鍵暗号方式との対比の土台となる、共通鍵暗号方式の基本定義を確認する。","kid":"共通鍵暗号方式は、鍵を1本だけ用意して、その同じ鍵で「暗号化する（隠す）」のも「復号する（元に戻す）」のも行う方式。","eg":"たとえるなら、1本の鍵で開けるのも閉めるのもできる、ふつうの南京錠のイメージ。閉めるときも開けるときも同じ鍵を使う。","terms":[["共通鍵暗号方式","暗号化と復号に同じ1つの鍵を使う暗号方式。処理が速いのが利点"],["復号","暗号化されたデータを、元の読める状態に戻すこと"]],"think":"共通鍵暗号方式は計算が単純なぶん処理が速いという利点がある一方、「その鍵をどうやって相手に安全に渡すか」という鍵配送問題を抱えている、という弱点とセットで理解しておくと後の公開鍵暗号方式の話につながる。","vs":"公開鍵暗号方式と混同しやすいが、公開鍵暗号方式は暗号化用と復号用で異なる2つの鍵（公開鍵・秘密鍵）を使う点が違う。","opt":["正解。暗号化と復号に同じ1つの鍵を使う暗号方式。","公開鍵暗号方式は、暗号化用と復号用で異なる2つの鍵を使う方式で、共通鍵暗号方式とは仕組みが違う。","ハッシュ関数はデータから固定長の値を計算する仕組みで、元のデータに戻すこと（復号）は想定されていない。","デジタル署名は、データの作成者や改ざんの有無を確認するための仕組みで、暗号方式そのものの分類名ではない。"]}'),

  ('ap-server-q29', 'セキュリティの数理と認証',
   '共通鍵暗号方式には「その鍵をどうやって相手に安全に渡すか」という課題がある。この課題を「暗号化用の鍵は公開してもよい」という発想で解決した暗号方式を何というか。',
   NULL::text,
   '["公開鍵暗号方式", "共通鍵暗号方式", "ハッシュ関数", "ワンタイムパスワード"]',
   0, '[0]', 'single',
   '{"asked":"鍵配送問題を解決する暗号方式を選ぶ問題。","why_asked":"公開鍵暗号方式が「なぜ生まれたか」という動機（鍵配送問題の解決）を理解しているかを問う。","kid":"公開鍵暗号方式は、「暗号化するための鍵（公開鍵）」と「復号するための鍵（秘密鍵）」を別々に用意する。公開鍵は誰に見られても大丈夫なので、堂々と配ることができる。復号できる秘密鍵さえ本人が大事に持っていれば、鍵を安全に渡す方法に悩む必要がなくなる。","eg":"たとえるなら、誰でも投函はできるけど、開けるのは自分だけが持つ鍵でしかできない郵便受け。郵便受けの投函口（公開鍵）はみんなに教えても平気で、開ける鍵（秘密鍵）だけ自分で厳重に管理すればよい。","terms":[["公開鍵","誰に渡してもよい、暗号化専用の鍵"],["秘密鍵","本人だけが持つ、復号専用の鍵"],["鍵配送問題","共通鍵暗号方式で、鍵そのものをどう安全に相手に渡すかという課題"]],"think":"共通鍵暗号方式は「鍵そのものを秘密にする必要がある」ため、その鍵をどう安全に届けるかが悩みの種になる。公開鍵暗号方式は「暗号化用の鍵は公開してよい」という発想の転換で、そもそも鍵を秘密裏に届ける必要をなくした、という因果関係を押さえるとよい。","vs":"共通鍵暗号方式と混同しやすいが、共通鍵暗号方式は1本の鍵を両方に使うため鍵の受け渡しに注意が必要、公開鍵暗号方式は2本の鍵を使い分けることで受け渡しの悩みを解消している点が違う。","opt":["正解。暗号化用の鍵（公開鍵）を公開し、復号用の鍵（秘密鍵）だけを本人が管理することで鍵配送問題を解決した方式。","共通鍵暗号方式はまさに鍵配送問題を抱える側の方式であり、それを解決した方式として選ぶのは誤り。","ハッシュ関数はデータの改ざん検知などに使われる仕組みで、鍵配送問題の解決を目的としたものではない。","ワンタイムパスワードは一度しか使えない使い捨てのパスワードの仕組みで、鍵配送問題の解決とは別の話。"]}'),

  ('ap-server-q30', 'セキュリティの数理と認証',
   'あるデータから、決まった手順で固定長の短い値を計算し、データが少しでも変わるとその値も大きく変わる性質を持つ仕組みを何というか。改ざんの検知などに使われる。',
   NULL::text,
   '["ハッシュ関数", "共通鍵暗号方式", "公開鍵暗号方式", "ロードバランサ"]',
   0, '[0]', 'single',
   '{"asked":"データから固定長の値を計算し、改ざん検知に使われる仕組みを問う問題。","why_asked":"暗号化（元に戻せる）とハッシュ（元に戻せない）の違いを区別できるかを問う定番論点。","kid":"ハッシュ関数は、どんなに長いデータを入れても、決まった長さの短い「指紋」のような値を作り出す仕組み。同じデータからは必ず同じ指紋ができるけど、データが少しでも変わると指紋もまったく別のものに変わる。この性質を利用して「データが改ざんされていないか」を確認できる。","eg":"たとえるなら、書類のページ数を数えて記録しておくようなイメージ。誰かが1枚こっそり抜き取ったり書き換えたりすると、後で数え直したときに合計が変わって気づける。","terms":[["ハッシュ関数","データから固定長の値（ハッシュ値）を計算する仕組み。同じ入力からは必ず同じ値になり、元のデータに戻すことはできない"],["改ざん検知","データが送信中や保存中に不正に書き換えられていないかを確認すること"]],"think":"ハッシュ関数の最大の特徴は「元に戻せない（一方向性）」という点。暗号化は「元に戻すこと（復号）」が前提だが、ハッシュ関数は逆にそれができないことを利用して、パスワードの保管や改ざん検知に使われる。","vs":"暗号化と混同しやすいが、暗号化は「正しい鍵があれば元のデータに戻せる」のに対し、ハッシュ関数は「一度計算したら元のデータには戻せない」という決定的な違いがある。","opt":["正解。データから固定長の値を計算し、少しの変化でも大きく値が変わる、改ざん検知等に使われる仕組み。","共通鍵暗号方式は暗号化と復号に同じ鍵を使う方式で、元のデータに戻すことを前提とした仕組みである。","公開鍵暗号方式は暗号化用と復号用で異なる鍵を使う方式で、こちらも元のデータに戻すことを前提としている。","ロードバランサは複数のサーバーへ処理を振り分ける仕組みで、データの改ざん検知とは無関係。"]}'),

  ('ap-server-q31', 'セキュリティの数理と認証',
   'Webサイトが提示する公開鍵が「本当にそのサイトの運営者のものである」ことを、信頼できる第三者機関が証明する仕組みを何というか。',
   NULL::text,
   '["PKI（公開鍵基盤）による電子証明書", "共通鍵暗号方式", "ハッシュ関数", "ワンタイムパスワード"]',
   0, '[0]', 'single',
   '{"asked":"公開鍵の持ち主を第三者が証明する仕組みを問う問題。","why_asked":"公開鍵暗号方式だけでは「その公開鍵が本当に正しい相手のものか」を確認できない、という一段深い課題を理解しているかを問う。","kid":"公開鍵暗号方式は便利だけど、「この公開鍵は本当にA社のものです」と誰かが保証してくれないと、なりすましの公開鍵を渡されても気づけない。PKIは、信頼できる第三者（認証局）が「この公開鍵は確かにこの人のものです」という電子的な証明書を発行してくれる仕組み。","eg":"たとえるなら、印鑑証明のような仕組み。ただの印鑑（公開鍵）だけでは誰のものか分からないけど、役所（認証局）が発行した印鑑証明書があれば、その印鑑が本人のものだと確認できる。","terms":[["PKI","Public Key Infrastructureの略。直訳は「公開鍵・基盤」。公開鍵の持ち主を保証する仕組み全体"],["認証局","公開鍵と持ち主の対応関係を保証し、電子証明書を発行する信頼できる第三者機関"]],"think":"公開鍵暗号方式だけでは「誰の公開鍵か」を確認する手段がない。PKIはこの穴を埋めるために、信頼できる第三者（認証局）が間に入って保証する仕組みとして生まれた、という因果関係で理解する。","vs":"公開鍵暗号方式そのものと混同しやすいが、公開鍵暗号方式は「暗号化・復号の仕組み」、PKIは「その公開鍵が本物かどうかを保証する仕組み」で、役割の階層が違う。","opt":["正解。信頼できる第三者機関（認証局）が、公開鍵と持ち主の対応関係を電子証明書として保証する仕組み。","共通鍵暗号方式は暗号化と復号に同じ鍵を使う方式で、公開鍵の持ち主を証明する仕組みではない。","ハッシュ関数はデータの改ざん検知などに使われる仕組みで、公開鍵の持ち主を保証するものではない。","ワンタイムパスワードは一度しか使えない使い捨てのパスワードの仕組みで、公開鍵の証明とは別の話。"]}'),

  ('ap-server-q32', 'セキュリティの数理と認証',
   '公開鍵暗号方式を使って「送信者が確かに本人であること」と「データが改ざんされていないこと」を確認する仕組みで、送信者が自分の秘密鍵でデータに印を付け、受信者が送信者の公開鍵でその印を確認するものを何というか。',
   NULL::text,
   '["デジタル署名", "共通鍵暗号方式", "ハッシュ関数単体の利用", "ロードバランシング"]',
   0, '[0]', 'single',
   '{"asked":"秘密鍵で印を付け公開鍵で確認する仕組み（デジタル署名）を問う問題。","why_asked":"公開鍵暗号方式の「暗号化(公開鍵)→復号(秘密鍵)」という向きと、デジタル署名の「署名(秘密鍵)→確認(公開鍵)」という逆向きの使い方を区別できるかを問う。","kid":"ふだんの公開鍵暗号は「公開鍵で鍵をかけて、秘密鍵で開ける」という使い方。デジタル署名はこれを逆にして、「秘密鍵でハンコを押して、公開鍵でそのハンコが本物か確認する」という使い方をする。本人しか持っていない秘密鍵でハンコを押しているので、公開鍵で確認できれば「確かに本人が押した」と分かる。","eg":"たとえるなら、本人しか持っていない特別なハンコ（秘密鍵）を書類に押し、誰でも持っている見本帳（公開鍵）と照らし合わせて「確かにこの人のハンコだ」と確認するイメージ。","terms":[["デジタル署名","秘密鍵で印を付け、対応する公開鍵で本人性と改ざんの有無を確認する仕組み"]],"think":"公開鍵暗号方式は「誰でも暗号化できるが、開けられるのは本人だけ」という秘密保持が目的。デジタル署名は逆に「本人しか印を付けられないが、印が本物かは誰でも確認できる」という本人確認・改ざん検知が目的、という使い方の向きの違いで整理する。","vs":"通常の公開鍵暗号方式（データを秘密にする用途）と混同しやすいが、デジタル署名は鍵を使う向きが逆で、目的も「秘密にする」ことではなく「本人確認・改ざん検知」であるという点が違う。","opt":["正解。送信者が秘密鍵で印を付け、受信者が送信者の公開鍵でその印を確認する仕組み。","共通鍵暗号方式は1本の鍵を暗号化・復号の両方に使う方式で、本人確認の仕組みとしては使われない。","ハッシュ関数単体では改ざんの検知はできても、それが「誰によって作られたものか」という本人確認まではできない。","ロードバランシングは複数サーバーへ処理を振り分ける仕組みで、本人確認や改ざん検知とは無関係。"]}'),

  ('ap-server-q33', 'セキュリティの数理と認証',
   '共通鍵暗号方式と公開鍵暗号方式を比べたとき、一般的な特徴として正しいものはどれか。',
   NULL::text,
   '["共通鍵暗号方式の方が計算処理が速く、公開鍵暗号方式は鍵配送の課題を解決できる", "公開鍵暗号方式の方が計算処理が速く、共通鍵暗号方式は鍵配送の課題を解決できる", "どちらも処理速度・鍵配送のしやすさに違いはない", "共通鍵暗号方式は暗号化にしか使えず、復号はできない"]',
   0, '[0]', 'single',
   '{"asked":"共通鍵暗号方式と公開鍵暗号方式のそれぞれの特徴（速度・鍵配送）を問う問題。","why_asked":"両方式を組み合わせるハイブリッド暗号方式（実際のHTTPS通信などで使われる考え方）を理解する前提として、両者のトレードオフを押さえさせる。","kid":"共通鍵暗号方式は計算がシンプルなので処理が速いけど、鍵をどう安全に渡すかという悩みを抱えている。公開鍵暗号方式は鍵を配る悩みを解決できるけど、計算が複雑なぶん処理は遅くなりがち。この2つは、それぞれ得意なことが違う。","eg":"たとえるなら、共通鍵暗号方式は「速いけど鍵の受け渡しが心配な普通の鍵」、公開鍵暗号方式は「鍵の受け渡しは安心だけど、鍵を作ったり開けたりするのに時間がかかる複雑な鍵」というイメージ。","terms":[["ハイブリッド暗号方式","公開鍵暗号方式で共通鍵を安全に届け、実際のデータのやり取りは速い共通鍵暗号方式で行う、両者の長所を組み合わせた方式"]],"think":"実際のHTTPS通信では、最初に公開鍵暗号方式で「共通鍵を安全に届ける」部分だけを行い、その後の実際のデータのやり取りは速い共通鍵暗号方式で行う、という組み合わせ（ハイブリッド暗号方式）が使われている。これは両方式の長所（速さと、鍵配送の安全性）をいいとこ取りする発想。","vs":"「公開鍵暗号方式の方がすべての面で優れている」という誤解に注意。公開鍵暗号方式は鍵配送問題を解決する代わりに、計算コストが高く処理が遅いというトレードオフを持つ。","opt":["正解。共通鍵暗号方式は処理が速く、公開鍵暗号方式は鍵配送の課題を解決できるという、それぞれ異なる強みを持つ。","処理速度と鍵配送のしやすさが逆になっており、この記述は誤り。","共通鍵暗号方式は鍵配送に課題を抱え、公開鍵暗号方式は計算コストが高く処理が遅いという、明確な違いがある。","共通鍵暗号方式は同じ鍵を使って暗号化と復号の両方を行える方式であり、復号ができないという記述は誤り。"]}'),

  ('ap-server-q34', 'データベースの基礎',
   'データベースの設計で、同じ情報をあちこちのテーブルに重複して持たないように整理していく作業を何というか。',
   NULL::text,
   '["正規化", "インデックス化", "ロールバック", "コミット"]',
   0, '[0]', 'single',
   '{"asked":"データの重複をなくすように整理する作業（正規化）の名前を問う問題。","why_asked":"正規化という言葉の「動機」を理解する入口。テーブルを分ける理由を丸暗記ではなく納得して覚えるための最初の問い。","kid":"正規化は、同じ情報をいろんな場所に何度も書かなくて済むように、テーブルを整理していく作業。例えば「注文」の表に毎回お客さんの住所を書き写すのではなく、「お客さん」の表を別に作って、そこだけ住所を管理すれば、住所が変わったときも1か所直すだけで済む。","eg":"たとえるなら、クラス名簿にみんなの住所を書くとき、同じ住所の家族が複数人いる場合でも、1人ずつ全部の住所欄に書き写すのではなく、「家族の住所一覧」を別の紙にまとめておいて、名簿には「どの家族か」だけ書いておく、というイメージ。住所が変わったときも1か所直すだけで済む。","terms":[["正規化","データの重複をなくし、1つの情報は1か所にだけ持たせるようにテーブルを整理していく設計手法"]],"think":"正規化の目的は「同じ情報を何度も書かなくて済むようにする（＝修正が1か所で済む、矛盾が起きにくくなる）」こと。この動機を先に理解しておくと、第1〜3正規形のような細かいルールも「何のためにやっているか」が腑に落ちやすい。","vs":"インデックス化と混同しやすいが、インデックス化は検索を速くするための工夫であり、正規化のようにデータの重複や整理を目的としたものではない。","opt":["正解。同じ情報の重複をなくすように、テーブルを整理していく設計作業。","インデックス化は検索を高速化するための仕組みで、データの重複解消を目的とした作業ではない。","ロールバックはトランザクションの途中の変更を取り消して元の状態に戻す操作で、テーブル設計の作業ではない。","コミットはトランザクションでの変更を確定させる操作で、テーブル設計の作業ではない。"]}'),

  ('ap-server-q35', 'データベースの基礎',
   '1つのマス目（列）に、複数の値をまとめて詰め込むのではなく、1つの値だけを入れるように整理することを目指す正規化の段階を何というか。',
   NULL::text,
   '["第1正規形", "第2正規形", "第3正規形", "非正規形"]',
   0, '[0]', 'single',
   '{"asked":"1つの列に1つの値だけを入れるという正規化の段階（第1正規形）を問う問題。","why_asked":"正規化の第一歩がどんな状態を目指すものかを、具体的なイメージで理解しているかを問う。","kid":"第1正規形は、1つのマス目に「りんご、みかん、ぶどう」のように複数の値をまとめて詰め込むのをやめて、1つのマス目には1つの値だけを入れるように整理する段階。","eg":"たとえるなら、1つの引き出しにいろんな種類の文房具をごちゃまぜに入れるのをやめて、「鉛筆はここ、消しゴムはここ」というふうに1つの引き出しには1種類だけを入れるように整理するイメージ。","terms":[["第1正規形","1つの列（マス目）に複数の値をまとめて入れず、1つの値だけを入れるように整理した状態"]],"think":"正規化は段階を追って進むもので、第1正規形はその最初の一歩。「1マス1値」というシンプルなルールから始まり、次第により細かい重複（部分的な重複、間接的な重複）を取り除いていく、という流れで理解する。","vs":"第2正規形・第3正規形と混同しやすいが、第1正規形は「1マスに複数値を入れない」という最も基本的なルールで、第2・第3正規形はその先の、より細かい種類の重複（列どうしの依存関係）を取り除く段階になる。","opt":["正解。1つの列に複数の値をまとめて入れず、1つの値だけを入れるように整理した段階。","第2正規形は、さらにキーの一部だけに依存する列（部分関数従属）を切り出す、より進んだ段階の整理。","第3正規形は、キー以外の列に依存している列（推移的関数従属）を切り出す、さらに進んだ段階の整理。","非正規形は、まだ正規化が行われていない、複数の値が1マスに詰め込まれたままの状態を指す。"]}'),

  ('ap-server-q36', 'データベースの基礎',
   '注文テーブルに「商品名」と「商品の単価」の両方を持たせていると、同じ商品を何度も注文するたびに商品名と単価を重複して書くことになり、単価を変更するときに全部の行を修正する必要が出てくる。この問題を解決する正規化の考え方として最も適切なものはどれか。',
   NULL::text,
   '["「商品」の情報を別テーブルに切り出し、注文テーブルからは商品IDだけで参照するようにする", "注文テーブルの列をすべて削除し、商品テーブルだけで管理する", "同じ商品の注文はすべて1行にまとめ、数量の列だけで管理する", "商品名と単価を毎回コピーし続けることで、検索を速くする"]',
   0, '[0]', 'single',
   '{"asked":"商品情報の重複を解消するための正規化の具体的な考え方を問う問題。","why_asked":"正規化の動機（重複の解消・修正箇所の一元化）を、具体的なテーブル設計の場面に当てはめて考えられるかを問う。","kid":"「商品」という情報は、注文のたびに何度も書き写すのではなく、「商品」だけをまとめた別の表を1つ作っておいて、注文の表からは「どの商品か（商品ID）」だけを指させばよい。そうすれば、単価が変わったときも商品の表を1か所直すだけで、すべての注文に反映される。","eg":"たとえるなら、辞書の中で同じ単語の説明を何度も書き写すのではなく、索引番号だけを書いておいて、本体の説明は辞書の該当ページ（別の場所）にまとめておく、というイメージ。説明を直したいときも1か所直すだけで済む。","terms":[["商品ID","それぞれの商品を区別するための番号。テーブルどうしをつなぐ「合言葉」のような役割を持つ"]],"think":"重複している情報（商品名・単価）を、その情報だけをまとめた別テーブルに切り出し、元のテーブルからは「番号（ID）」だけで参照する、というのが正規化の基本パターン。これにより、情報を直す場所が1か所に集約される。","vs":"「注文テーブルの列を全部消してしまう」という極端な案と混同しないこと。正規化は「重複する情報だけ」を別テーブルに切り出すのであって、注文自体の情報（数量や注文日など）まで消してしまうわけではない。","opt":["正解。商品情報を別テーブルに切り出し、注文テーブルからは商品IDだけで参照することで、修正箇所を1か所に集約できる。","注文テーブルの列をすべて削除してしまうと、誰がいつ何個注文したかという注文自体の情報が管理できなくなってしまう。","同じ商品の注文を1行にまとめてしまうと、注文日や注文者ごとの履歴が区別できなくなり、情報が失われてしまう。","商品名と単価をコピーし続けることは、まさに正規化が解決しようとしている「重複による修正の手間」をそのまま残す方法であり、解決策ではない。"]}'),

  ('ap-server-q37', 'データベースの基礎',
   '複数の処理（例えば「口座Aから引き落とし」と「口座Bへ入金」）をひとまとまりの単位として扱い、途中で失敗したら全部無かったことにする仕組みを何というか。',
   NULL::text,
   '["トランザクション", "インデックス", "パーティション", "レプリケーション"]',
   0, '[0]', 'single',
   '{"asked":"複数の処理をひとまとまりとして扱う仕組み（トランザクション）を問う問題。","why_asked":"データベースの信頼性を支える基本概念の入口。ACID特性を理解する前提として、まずトランザクションそのものの定義を確認する。","kid":"トランザクションは、いくつかの処理を「全部まとめて成功する」か「全部まとめて失敗する（無かったことにする）」かのどちらかにする仕組み。振込で「引き落としだけ成功して、入金の方は失敗した」なんてことが起きたら大変なので、こういう仕組みが要る。","eg":"たとえるなら、両替のときに「1万円札を渡す」のと「千円札10枚を受け取る」のを、どちらか一方だけで終わらせず、必ずセットで成立させる約束事のようなもの。片方だけ成立してしまうと、お金が消えたり増えたりしてしまう。","terms":[["トランザクション","複数の処理をひとまとまりの単位として扱い、途中で失敗したらすべて取り消す仕組み"]],"think":"トランザクションが無いと、複数の処理の途中でエラーが起きたときに「一部だけ実行された中途半端な状態」が残ってしまう。これを防ぐために「全部成功」か「全部失敗（取り消し）」のどちらかに揃える、というのがトランザクションの目的。","vs":"インデックスと混同しやすいが、インデックスは検索を速くするための仕組みであり、複数の処理をひとまとまりにする仕組みではない。","opt":["正解。複数の処理をひとまとまりとして扱い、途中で失敗したらすべて取り消す仕組み。","インデックスは検索を高速化するための仕組みで、複数処理をまとめる仕組みではない。","パーティションはデータを複数の領域に分割して管理する仕組みで、処理をまとめる仕組みとは別の観点。","レプリケーションはデータの複製をリアルタイムで作り続ける仕組みで、処理をまとめる仕組みとは別の観点。"]}'),

  ('ap-server-q38', 'データベースの基礎',
   'トランザクションが備えるべき4つの性質（原子性・一貫性・独立性・永続性）をまとめて何と呼ぶか。',
   NULL::text,
   '["ACID特性", "CAP定理", "SPOF", "RAID"]',
   0, '[0]', 'single',
   '{"asked":"トランザクションの4つの性質をまとめた呼び名を問う問題。","why_asked":"ACIDという頭字語と、それが指す4つの性質の対応関係を確認する定番論点。","kid":"ACID特性は、トランザクションが守るべき4つの約束事の頭文字を並べたもの。「全部成功か全部失敗か（原子性）」「データのつじつまが合っていること（一貫性）」「他の処理に途中経過を見せないこと（独立性）」「一度確定したら消えないこと（永続性）」の4つ。","eg":"たとえるなら、料理のレシピにある4つの絶対条件のようなもの。どれか1つでも守られないと、安心して料理を任せられなくなる。","terms":[["ACID","Atomicity(原子性)・Consistency(一貫性)・Isolation(独立性)・Durability(永続性)の頭文字"],["原子性","トランザクションの中の処理は「全部成功」か「全部失敗」のどちらかになるという性質"]],"think":"4つの性質を丸暗記するより、「なぜその性質が必要か」を1つずつイメージすると覚えやすい。原子性が無いと中途半端な処理が残る、独立性が無いと他の処理から変な途中経過が見えてしまう、永続性が無いと確定したはずのデータが消えてしまう、というように、それぞれが守っている「困りごと」を紐づけて覚える。","vs":"CAP定理と混同しやすいが、CAP定理は分散システムにおける「一貫性・可用性・分断耐性は3つ同時に満たせない」という別の理論であり、ACID特性（1つのトランザクションが満たすべき性質）とは対象が異なる。","opt":["正解。原子性・一貫性・独立性・永続性の4つの性質をまとめた呼び名。","CAP定理は分散システムにおける一貫性・可用性・分断耐性のトレードオフを説明する定理で、ACID特性とは別の理論。","SPOFはシステム全体を止めてしまう単一の箇所を指す用語で、トランザクションの性質を表すものではない。","RAIDは複数のディスクを組み合わせて信頼性や速度を高める仕組みで、トランザクションの性質を表すものではない。"]}'),

  ('ap-server-q39', 'データベースの基礎',
   'トランザクションの途中で行った変更を確定させる操作と、途中の変更を取り消して元の状態に戻す操作の組み合わせとして正しいものはどれか。',
   NULL::text,
   '["確定はコミット、取り消しはロールバック", "確定はロールバック、取り消しはコミット", "確定も取り消しもコミットで行う", "確定も取り消しもロールバックで行う"]',
   0, '[0]', 'single',
   '{"asked":"トランザクションの確定操作と取り消し操作の名前の対応を問う問題。","why_asked":"コミットとロールバックという2つの基本操作を、意味を取り違えずに覚えているかを問う。","kid":"コミットは「これで決定！もう変更しません」と確定させる操作。ロールバックは「やっぱりなかったことにします」と、変更前の状態に巻き戻す操作。","eg":"たとえるなら、コミットは「注文を確定するボタン」を押すこと。ロールバックは「注文をキャンセルして、カートを空にする」ことに近い。","terms":[["コミット","トランザクションの中で行った変更を確定させる操作"],["ロールバック","トランザクションの中で行った変更を取り消し、開始前の状態に戻す操作"]],"think":"「commit＝約束する・確定する」「rollback＝転がして戻す・巻き戻す」という英単語の意味からもそのままイメージできる。原子性（全部成功か全部失敗か）を実現するために、この2つの操作がセットで用意されている。","vs":"コミットとロールバックを逆に覚えてしまう間違いに注意。コミットは前向きに確定する操作、ロールバックは後ろ向きに巻き戻す操作、と方向のイメージで区別するとよい。","opt":["正解。確定させる操作がコミット、取り消して元に戻す操作がロールバック。","コミットとロールバックの役割が入れ替わっており、この記述は逆になっている。","コミットは確定の操作であり、取り消しの操作としては使われない。","ロールバックは取り消しの操作であり、確定の操作としては使われない。"]}'),

  ('ap-server-q40', 'データベースの基礎',
   '簡単なSQL文「SELECT name FROM users WHERE age >= 20」が行っている処理として最も適切な説明はどれか。',
   NULL::text,
   '["usersテーブルから、年齢が20以上の行を選び、name列の値を取り出す", "usersテーブルに、名前と年齢が20以上の新しい行を追加する", "usersテーブルから、年齢が20未満の行をすべて削除する", "usersテーブルのage列の値を、一律で20に書き換える"]',
   0, '[0]', 'single',
   '{"asked":"基本的なSELECT文が何を行っているかを読み解く問題。","why_asked":"SQL構文を丸暗記させるのではなく、キーワード（SELECT/FROM/WHERE）の役割から処理内容を読み解く力を確認する。","kid":"SELECTは「取り出す列」を指定し、FROMは「どの表から」を指定し、WHEREは「どんな条件の行だけ」を指定する。この文は「usersという表から、年齢が20以上の行だけを選んで、その中のname（名前）の値を取り出してね」という意味になる。","eg":"たとえるなら、名簿（usersテーブル）から「20歳以上の人」だけを探し出して、その人たちの名前だけをメモ用紙に書き出す作業をお願いしているイメージ。","terms":[["SELECT","取り出したい列を指定するキーワード"],["FROM","どのテーブル（表）から取り出すかを指定するキーワード"],["WHERE","取り出す行の条件を指定するキーワード"]],"think":"SQL文は「SELECT（何を）FROM（どこから）WHERE（どんな条件で）」という順番で読み解くと、日本語の文章のように意味が取れる。この文では「name（何を）」「usersテーブル（どこから）」「age >= 20（どんな条件で）」という組み立てになっている。","vs":"「行を削除する」「値を書き換える」という操作と混同しやすいが、SELECTはあくまで「データを読み取って表示する」ための命令であり、テーブルの中身を変更する命令（DELETEやUPDATE）とは別物。","opt":["正解。年齢が20以上の行を選び、その行のname列の値を取り出す（読み取る）処理。","新しい行を追加するのはINSERT文の役割であり、SELECT文は既存のデータを読み取るための命令。","行を削除するのはDELETE文の役割であり、SELECT文はデータを削除する命令ではない。","値を書き換えるのはUPDATE文の役割であり、SELECT文はデータを変更する命令ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-server'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
